import random, time, numpy as np
from scipy.integrate import solve_ivp
from solver import Solver

def ref(p):
    beta=p['params']['beta']; sigma=p['params']['sigma']; gamma=p['params']['gamma']; omega=p['params']['omega']
    def f(t,y):
        S,E,I,R=y
        return [-beta*S*I + omega*R, beta*S*I-sigma*E, sigma*E-gamma*I, gamma*I-omega*R]
    sol=solve_ivp(f,(p['t0'],p['t1']),p['y0'],method='DOP853',rtol=1e-8,atol=1e-10)
    return sol.y[:,-1], sol.nfev

s=Solver(); random.seed(2)
for label, maxlogt in [('moderate',3.3),('long',4.5)]:
    bad=0; maxerr=0; times=[]; refs=[]
    for k in range(60):
        x=np.array([random.random() for _ in range(4)]); x=x/x.sum()
        p={'t0':0.0,'t1':10**random.uniform(-1,maxlogt),'y0':x.tolist(),'params':{
            'beta':10**random.uniform(-2,0.5),
            'sigma':10**random.uniform(-2,0.3),
            'gamma':10**random.uniform(-2,0.3),
            'omega':10**random.uniform(-4,-0.3),
        }}
        ta=time.perf_counter(); a=np.array(s.solve(p)); times.append(time.perf_counter()-ta)
        b,n=ref(p); refs.append(n)
        err=np.max(np.abs(a-b)/(1e-8+1e-5*np.abs(b)))
        if err>maxerr: maxerr=err; worst=(err,p,a,b,n)
        if not np.allclose(a,b,rtol=1e-5,atol=1e-8): bad+=1
    print(label,'bad',bad,'maxerr',maxerr,'avg_us',np.mean(times)*1e6,'max_us',np.max(times)*1e6,'avg_nfev',np.mean(refs))
    if bad: print('worst',worst)
